import{_ as a,o as i,c as s,a9 as t}from"./chunks/framework.asyjyako.js";const k=JSON.parse('{"title":"Choose an interface","description":"","frontmatter":{},"headers":[],"relativePath":"interfaces/packages.md","filePath":"interfaces/packages.md","lastUpdated":null}'),n={name:"interfaces/packages.md"};function r(l,e,o,p,h,c){return i(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="Choose-an-interface" tabindex="-1">Choose an interface <a class="header-anchor" href="#Choose-an-interface" aria-label="Permalink to &quot;Choose an interface {#Choose-an-interface}&quot;">​</a></h1><p>All interfaces read the same saved runs; none of them changes what a measurement means.</p><ul><li><p>Run one item while editing — <a href="./vscode">VS Code</a></p></li><li><p>Select workloads and versions in a browser — <a href="./web-studio">Web interface (Oxygen)</a></p></li><li><p>Work from a terminal — <a href="./repl-pluto">REPL</a></p></li><li><p>Select suite runs with terminal keys — <a href="/PerfChecker/dev/interfaces/packages#Optional-terminal-UI">optional Tachikoma UI</a></p></li><li><p>Keep an editable notebook — <a href="./repl-pluto">Pluto</a></p></li><li><p>Explore or export measured plots — <a href="./visualization">Makie</a></p></li><li><p>Put saved measurements in your own docs — <a href="./documentation">Documenter</a></p></li></ul><p><a id="What-to-have-ready"></a><a id="Which-package-supplies-each-interface?"></a></p><h2 id="Which-package-supplies-it" tabindex="-1">Which package supplies it <a class="header-anchor" href="#Which-package-supplies-it" aria-label="Permalink to &quot;Which package supplies it {#Which-package-supplies-it}&quot;">​</a></h2><ul><li><p><strong>PerfChecker</strong> — Julia API, command line, text REPL.</p></li><li><p><strong>PerfCheckerWeb</strong> — Oxygen studio and HTTP endpoints.</p></li><li><p><strong>PerfCheckerPluto</strong> — notebook controls and Pluto launch.</p></li><li><p><strong>PerfCheckerMakie</strong> — Makie figures; WGLMakie adds interactive HTML.</p></li><li><p><strong>PerfCheckerTachikoma</strong> — optional terminal selection and saved-result views.</p></li><li><p><strong>VS Code extension</strong> — Testing view, commands, investigation panel.</p></li></ul><p>Load the package that supplies the interface. If two interfaces need conflicting dependencies, put them in separate environments and open the same saved run in each.</p><p>See <a href="./../guide/installation">Installation</a> for what to add.</p><h2 id="Optional-terminal-UI" tabindex="-1">Optional terminal UI <a class="header-anchor" href="#Optional-terminal-UI" aria-label="Permalink to &quot;Optional terminal UI {#Optional-terminal-UI}&quot;">​</a></h2><p>PerfCheckerTachikoma is a <strong>1.0.1 source companion</strong>, loaded explicitly rather than enabled by default. It uses Tachikoma 2.7 and UnicodePlots 3. It is not a separately registered package; its <a href="https://github.com/Mirage-Interactive-Fr/PerfChecker.jl/tree/1a7577da782ba8676683f3ceefcb8dccf055afe5/packages/PerfCheckerTachikoma" target="_blank" rel="noreferrer">source and installation recipe</a> are in <code>packages/PerfCheckerTachikoma</code> at revision <code>1a7577da</code>.</p><p>After preparing that companion and your suite&#39;s controller:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PerfChecker, PerfCheckerTachikoma</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">suite </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> load_software_suite</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;perf/suite.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tui</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">tui_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">plan_suite</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(suite; profile </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> :quick</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)))</span></span></code></pre></div><p>Opening the interface starts no measurement. <strong>Space</strong> selects runs, <strong>R</strong> launches the selection, <strong>C</strong> cancels and <strong>P</strong> plots completed evidence. To inspect a saved run without a launch action, use <code>tui(read_run_bundle(bundle_directory))</code>. UnicodePlots is the text fallback; optional Makie raster output needs a terminal with supported graphics. Controlled terminal-stream and raster tests do not establish support in every physical terminal, on macOS or on Windows.</p>`,13)])])}const u=a(n,[["render",r]]);export{k as __pageData,u as default};
